create function public.teacher_apply_override(
  p_room_code text,p_teacher_token text,p_override_action text,p_reason text
) returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_result jsonb;v_override_id uuid;v_scope jsonb;v_updated integer;
begin
  v_result:=public.teacher_apply_override_v056(p_room_code,p_teacher_token,p_override_action,p_reason);

  if (v_result->>'source_scene',v_result->>'source_phase') in
     (('act2_first_contact','meeting_discussion'),('act5_route_discussion','discussion')) then
    v_override_id:=(v_result->>'override_id')::uuid;
    select o.invalidated_scope into strict v_scope
    from public.teacher_overrides o where o.override_id=v_override_id;

    update public.runtime_events e
    set details=jsonb_set(e.details,'{invalidated_scope}',v_scope,true)
    where e.interaction_id=v_override_id and e.event_type='teacher_override';
    get diagnostics v_updated=row_count;
    if v_updated<>1 then
      raise exception 'Expected one canonical Teacher Override event, updated %.',v_updated;
    end if;
  end if;
  return v_result;
end$$;

create function public.asset_report_load_failure(
  p_asset_key text,p_version integer,p_storage_path text
) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_recorded boolean:=false;
begin
  perform pg_advisory_xact_lock(hashtextextended('asset-load:'||coalesce(p_asset_key,''),0));
  if not exists(
    select 1 from public.asset_registry_projection r
    join public.asset_candidates c on c.asset_key=r.asset_key and c.version=r.active_version
    where r.asset_key=p_asset_key and c.status='ACTIVE' and c.version=p_version
      and c.storage_path=p_storage_path and c.published_at is not null
  ) then
    raise exception 'Asset failure report does not match current ACTIVE metadata.';
  end if;

  if not exists(
    select 1 from public.asset_events e
    where e.asset_key=p_asset_key and e.event_type='asset_load_failed' and e.version=p_version
      and e.details->>'reason'='ACTIVE_STORAGE_OBJECT_LOAD_FAILED'
      and e.details->>'storage_path'=p_storage_path
      and e.created_at>=now()-interval '5 minutes'
  ) then
    insert into public.asset_events(asset_key,event_type,version,details)
    values(p_asset_key,'asset_load_failed',p_version,jsonb_build_object(
      'reason','ACTIVE_STORAGE_OBJECT_LOAD_FAILED','storage_path',p_storage_path
    ));
    v_recorded:=true;
  end if;
  return jsonb_build_object('ok',true,'recorded',v_recorded,'reason','ACTIVE_STORAGE_OBJECT_LOAD_FAILED');
end$$;

create or replace function public.s9_start_formal_game(
  p_room_code text,
  p_teacher_token text,
  p_run_mode text
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  started jsonb;
  initialized jsonb;
begin
  -- Both calls execute in this transaction. Any initialization failure rolls
  -- back the run insert, so clients can never observe a committed half-start.
  started:=public.s2_start_run(p_room_code,p_teacher_token,p_run_mode);
  initialized:=public.s3b_initialize_flow(p_room_code,p_teacher_token);
  return started || jsonb_build_object(
    'formal_state','active',
    'canonical_flow_initialized',true,
    'canonical_run_id',initialized->'run_id'
  );
end;
$$;

create or replace function public.s5_ensure_initialized(p_run uuid) returns boolean
language plpgsql security definer set search_path=public as $$
declare room text;created_new boolean:=false;sid uuid;
begin
 perform 1 from public.game_runs where run_id=p_run for update;
 if not exists(select 1 from public.s3b_run_state where run_id=p_run and terminal_state='SPRINT3B_COMPLETE') then return false;end if;
 insert into public.s5_run_state(run_id)values(p_run)on conflict(run_id)do nothing;
 if found then
  created_new:=true;
  insert into public.s5_rounds(run_id,phase_key,vote_round,topic_text_key)
  values(p_run,'act6_vote',1,'act06.001')returning discussion_session_id into sid;
  update public.s3_runtime_scene_state set allow_share_photo=true where run_id=p_run;
  select room_code into room from public.game_runs where run_id=p_run;
  perform public.s2_log_event(p_run,room,null,'s5_prepared',null,
    jsonb_build_object('event_source','automatic_transition','prepared_discussion_session_id',sid,
      'timer_started',false,'behavior_scoring',false));
 end if;
 return created_new;
end;
$$;

create or replace function public.s9_enter_act6(
  p_room_code text,
  p_session_token text,
  p_expected_run_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  room text:=upper(trim(p_room_code));
  player public.s1_room_players%rowtype;
  active_run public.game_runs%rowtype;
  progress public.s3b_player_progress%rowtype;
  sprint5 public.s5_run_state%rowtype;
  entered_count integer;
  sid uuid;
begin
  player:=public.s1_get_player_by_session(room,p_session_token);
  active_run:=public.s2_get_active_run(room);
  if active_run.run_id is null or active_run.run_id<>p_expected_run_id then
    raise exception 'The formal run changed. Refresh before entering ACT 6.';
  end if;
  perform 1 from public.game_runs where run_id=active_run.run_id for update;
  if not exists(select 1 from public.s3b_run_state where run_id=active_run.run_id and terminal_state='SPRINT3B_COMPLETE') then
    raise exception 'ACT 5 is not complete.';
  end if;
  select * into sprint5 from public.s5_run_state where run_id=active_run.run_id for update;
  if not found then raise exception 'ACT 6 preparation is unavailable.';end if;
  select * into progress from public.s3b_player_progress
  where run_id=active_run.run_id and player_id=player.player_id for update;
  if progress.act6_handoff_observed_at is null then
    raise exception 'Observe the ACT 5 route consequence before entering ACT 6.';
  end if;
  if progress.act6_entered_at is null then
    update public.s3b_player_progress
    set player_location='portrait_hall',act6_entered_at=now()
    where run_id=active_run.run_id and player_id=player.player_id;
    perform public.s2_log_event(active_run.run_id,room,null,'act6_entered',player.player_id,
      jsonb_build_object('event_source','player_transition','player_location','portrait_hall','behavior_scoring',false));
  end if;
  select count(*) into entered_count from public.s3b_player_progress
  where run_id=active_run.run_id and act6_entered_at is not null;
  if entered_count=3 and sprint5.act6_entered_at is null then
    select discussion_session_id into sid from public.s5_rounds
    where run_id=active_run.run_id and phase_key='act6_vote' and vote_round=1;
    if sid is null then raise exception 'ACT 6 discussion preparation is unavailable.';end if;
    perform public.s5_configure_discussion(sid,'act6_vote');
    perform public.s5_set_scene(active_run.run_id,'act6_portrait','act6_vote','round_1','ACTION_SCREEN','act06.001');
    update public.s5_run_state set act6_entered_at=now(),updated_at=now() where run_id=active_run.run_id;
    perform public.s2_log_event(active_run.run_id,room,sid,'act6_discussion_started',null,
      jsonb_build_object('event_source','all_player_entry_barrier','entered_players',entered_count,'behavior_scoring',false));
  end if;
  return jsonb_build_object('ok',true,'run_id',active_run.run_id,'act6_entered',true,
    'player_location','portrait_hall','entered_players',entered_count,'discussion_started',entered_count=3);
end;
$$;

create or replace function public.s9_observe_act5_handoff(
  p_room_code text,
  p_session_token text,
  p_expected_run_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  room text:=upper(trim(p_room_code));
  player public.s1_room_players%rowtype;
  active_run public.game_runs%rowtype;
begin
  player:=public.s1_get_player_by_session(room,p_session_token);
  active_run:=public.s2_get_active_run(room);
  if active_run.run_id is null or active_run.run_id<>p_expected_run_id then
    raise exception 'The formal run changed. Refresh the ACT 5 handoff.';
  end if;
  perform 1 from public.game_runs where run_id=active_run.run_id for update;
  if not exists(select 1 from public.s3b_run_state where run_id=active_run.run_id and terminal_state='SPRINT3B_COMPLETE')
     or not exists(select 1 from public.s5_run_state where run_id=active_run.run_id) then
    raise exception 'The ACT 5 handoff is unavailable.';
  end if;
  update public.s3b_player_progress
  set act6_handoff_observed_at=coalesce(act6_handoff_observed_at,now())
  where run_id=active_run.run_id and player_id=player.player_id and act6_handoff_observed_at is null;
  if not found and not exists(select 1 from public.s3b_player_progress where run_id=active_run.run_id and player_id=player.player_id) then
    raise exception 'Player progress is unavailable.';
  end if;
  return jsonb_build_object('ok',true,'run_id',active_run.run_id,'handoff_observed',true);
end;
$$;

create or replace function public.s9_get_player_wait_state(p_room_code text,p_session_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;mine public.s6_choices%rowtype;submitted int:=0;role text;engaged boolean:=false;
begin
 p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);
 select * into s from public.s6_run_state where run_id=g.run_id;
 if not found then return jsonb_build_object('active',false);end if;
 select * into mine from public.s6_choices where run_id=g.run_id and phase_key=s.phase_key and round_no=s.round_no and player_id=p.player_id order by locked_at desc limit 1;
 if s.phase_key='act11_allocation' then
  select count(*) into submitted from public.s6_allocations where run_id=g.run_id;
 else
  select count(*) into submitted from public.s6_choices where run_id=g.run_id and phase_key=s.phase_key and round_no=s.round_no;
 end if;
 select role_key into role from public.s6_allocations where run_id=g.run_id and player_id=p.player_id;
 if role is not null then engaged:=exists(select 1 from public.s6_engagements where run_id=g.run_id and role_key=role and player_id=p.player_id);end if;
 return jsonb_build_object('active',true,'phase_key',s.phase_key,'round_no',s.round_no,
  'my_choice_locked',mine.player_id is not null,'submitted_count',submitted,
  'my_allocation_locked',role is not null,'my_role_key',role,'my_engaged',engaged,
  'engaged_count',(select count(*) from public.s6_engagements where run_id=g.run_id));
end$$;

create or replace function public.s3_get_player_state(p_room_code text,p_session_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;
begin
 p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);
 if g.run_id is null then return jsonb_build_object('active',false);end if;
 return jsonb_build_object('active',true,'run_id',g.run_id,
  'scene',(select to_jsonb(s) from public.s3_runtime_scene_state s where s.run_id=g.run_id),
  'items',(select coalesce(jsonb_agg(jsonb_build_object('item_key',i.item_key,'name_text_key',c.name_text_key,'current_view',v.current_view)order by i.acquired_at),'[]') from public.s3_player_items i join public.s3_item_catalog c using(item_key) left join public.s3_player_item_view_state v on v.run_id=i.run_id and v.player_id=i.physical_owner_id and v.item_key=i.item_key where i.run_id=g.run_id and i.physical_owner_id=p.player_id),
  'inspected_item_keys',(select coalesce(jsonb_agg(x.item_key order by x.inspected_at),'[]') from public.s9_pocket_item_inspections x where x.run_id=g.run_id and x.player_id=p.player_id),
  'observations',(select coalesce(jsonb_agg(to_jsonb(o)-'run_id'-'player_id'),'[]') from public.s3_player_observations o where o.run_id=g.run_id and o.player_id=p.player_id),
  'shared_photos',(select coalesce(jsonb_agg(to_jsonb(ph)-'run_id'-'received_by'),'[]') from public.s3_shared_photos ph where ph.run_id=g.run_id and ph.received_by=p.player_id),
  'group_items',(select coalesce(jsonb_agg(to_jsonb(gi)-'run_id'),'[]') from public.s3_group_items gi where gi.run_id=g.run_id),
  'knowledge',(select coalesce(jsonb_agg(to_jsonb(k)-'run_id'-'player_id'),'[]') from public.s3_player_knowledge k where k.run_id=g.run_id and k.player_id=p.player_id));
end$$;

create or replace function public.s3_set_item_view(p_room_code text,p_session_token text,p_item_key text,p_target_view text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;currentview text;scene text;
begin
 p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);
 if not exists(select 1 from public.s3_player_items where run_id=g.run_id and physical_owner_id=p.player_id and item_key=p_item_key) then raise exception 'Player does not physically own this item.';end if;
 if not exists(select 1 from public.s9_pocket_item_inspections where run_id=g.run_id and player_id=p.player_id and item_key=p_item_key) then raise exception 'Inspect the item before changing its view.';end if;
 if not exists(select 1 from public.s3_item_catalog where item_key=p_item_key and shareable_views ? p_target_view) then raise exception 'Invalid item view.';end if;
 select current_view into currentview from public.s3_player_item_view_state where run_id=g.run_id and player_id=p.player_id and item_key=p_item_key for update;
 if currentview is null then raise exception 'Item view state is not initialized.';end if;
 if currentview<>p_target_view and not ((currentview='front' and p_target_view='back') or(currentview='back' and p_target_view='front')) then raise exception 'Invalid item view transition.';end if;
 update public.s3_player_item_view_state set current_view=p_target_view,updated_at=now() where run_id=g.run_id and player_id=p.player_id and item_key=p_item_key;
 select scene_id into scene from public.s3_runtime_scene_state where run_id=g.run_id;
 if p_target_view='back' and p_item_key='gitte_number_note' then
  insert into public.s3b_player_facts values(g.run_id,p.player_id,'gitte_knows_star',now()) on conflict do nothing;
  perform public.s3_record_knowledge(g.run_id,p.player_id,'gitte_star_symbol','pocket_inspection',scene,null,p_item_key);
 elsif p_target_view='back' and p_item_key='linda_stopped_watch' then
  insert into public.s3b_player_facts values(g.run_id,p.player_id,'linda_watch_reminder',now()) on conflict do nothing;
  perform public.s3_record_knowledge(g.run_id,p.player_id,'linda_watch_reminder','pocket_inspection',scene,null,p_item_key);
 end if;
 return jsonb_build_object('ok',true,'current_view',p_target_view);
end$$;

create or replace function public.s9_inspect_pocket_item(p_room_code text,p_session_token text,p_item_key text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;scene text;
begin
